def classify_and_count(nums):
    positives = 0
    negatives = 0
    zeros = 0
    for n in nums:
        if n > 0:
            positives += 1
        elif n < 0:
            negatives += 1
        else:
            zeros += 1
    return positives, negatives, zeros
